(6464876, 960943, 114285, '<td valign="top">Different.</td>', 'Different.', '2011-07-08 01:56:31.000000', NULL, 1),
(6464930, 960926, 96530, '<td valign="top">Lol! I did some test shots of this same place! I never made it back when the light was good though. And just as well for both of us- two of the same thing in a challenge doesn''t bolster scores. Good luck! I know this place is a tough shoot with the big ugly new building surrounding it...</td>', 'Lol! I did some test shots of this same place! I never made it back when the light was good though. And just as well for both of us- two of the same thing in a challenge doesn''t bolster scores. Good luck! I know this place is a tough shoot with the big ugly new building surrounding it...', '2011-07-08 02:40:15.000000', NULL, 1),
(6464934, 960905, 96530, '<td valign="top">Nicely done! Very festive and colorful. I had something very similar in mind but didn''t get the time to try shooting it. Love the textured pattern showing in that seat...</td>', 'Nicely done! Very festive and colorful. I had something very similar in mind but didn''t get the time to try shooting it. Love the textured pattern showing in that seat...', '2011-07-08 02:46:27.000000', NULL, 1),
