(6465820, 960815, 114225, '<td valign="top">Very cool find. I bet they make some great sandwiches. I like the simple processing used.</td>', 'Very cool find. I bet they make some great sandwiches. I like the simple processing used.', '2011-07-08 20:50:03.000000', NULL, 1),
(6465824, 960919, 114225, '<td valign="top">This is a decent use of selective saturation to really pull the eyes in. Unfortunately the strange shading in the sky is very distracting.</td>', 'This is a decent use of selective saturation to really pull the eyes in. Unfortunately the strange shading in the sky is very distracting.', '2011-07-08 20:50:56.000000', NULL, 1),
(6465825, 960747, 114225, '<td valign="top">I was wondering if anyone would include McD''s. I''m glad that you did this with the old one around.</td>', 'I was wondering if anyone would include McD''s. I''m glad that you did this with the old one around.', '2011-07-08 20:51:26.000000', NULL, 1),
