(6466988, 960941, 39880, '<td valign="top">I like these kind of night shots.  I feel this would be better if it was more centered with less foreground.</td>', 'I like these kind of night shots.  I feel this would be better if it was more centered with less foreground.', '2011-07-10 14:43:20.000000', NULL, 1),
(6466989, 960769, 39880, '<td valign="top">A good street scene.</td>', 'A good street scene.', '2011-07-10 14:43:56.000000', NULL, 1),
(6467019, 960836, 23484, '<td valign="top">Excellent shot and processing.</td>', 'Excellent shot and processing.', '2011-07-10 16:20:48.000000', NULL, 1),
