(6467135, 960099, 39880, '<td valign="top">Cool looking place.  For me the colors and focus look a bit off.</td>', 'Cool looking place.  For me the colors and focus look a bit off.', '2011-07-10 19:49:05.000000', NULL, 1),
(6467147, 960905, 135405, '<td valign="top">Excellent color, saturation, composition, and (most importantly) NO GUM under the counter.  Now THAT''S a clean Diner.</td>', 'Excellent color, saturation, composition, and (most importantly) NO GUM under the counter.  Now THAT''S a clean Diner.', '2011-07-10 20:14:19.000000', NULL, 1),
